"""Review facts generated by the model, with explanations rendered from those facts."""

import copy
import json

from .review_contract import PROFILE_RULES, json_schema, parse_review


def facts_prompt(profile="persistence"):
    example = {
        "action": "finish", "task_kind": "edit",
        "field_readings": [{"field": "visible field label", "intent": "edit",
                            "requested_value": "task value",
                            "before": {"value": "literal entered value", "step": 3},
                            "after": {"value": "literal saved value", "step": 7},
                            "input_matches_request": True, "result_matches_request": True}],
        "submission": {"status": "accepted", "evidence": {"step": 4}},
        "result_observed": True, "result_steps": [7], "expected_rejection": False,
        "verdict": "pass", "evidence_steps": [3, 4, 7],
    }
    return (
        "Judge the public browser task from the supplied screenshots and executed actions. "
        "Return one evidence_facts_v1 finish JSON object. Read the exact visible field values "
        "and cite the supplied screenshot steps. Explanations are generated by the application.\n"
        "Use one field_readings item for every requested field, including fields to preserve. "
        "Read under its own visible label. Preserve exact signs, digits and characters. "
        "intent is edit, preserve or generated; task_kind is edit or create. requested_value "
        "comes from the public task; use 'unchanged' when no literal preservation baseline "
        "is given, or the task's naming rule for generated values.\n"
        "For edit, before is the entered value before submission; for preserve, before is "
        "the original baseline. after is the same record's final visible value after saving "
        "and reopening. Each reading is null when absent, unseen or unreadable, or "
        "{value:string,step:integer}. A visibly empty field has value='', never null. "
        "A type action is no substitute for a screenshot reading.\n"
        "input_matches_request is true/false from the edit's visible before value, or null "
        "when unestablished; use null for preserve/generated. result_matches_request compares "
        "after with the task or preservation baseline, or is null when unestablished. "
        "A saved mismatch does not invalidate correctly entered input.\n"
        "submission.status is accepted, rejected or unknown; submission.evidence is "
        "{step:integer}, or null when unestablished. A Save click alone does not prove "
        "acceptance. Cancel/Back navigation is not submission. Establish the completed "
        "save separately from the final value. result_observed and result_steps identify "
        "the same record after completion, including a clearly identified list row.\n"
        "Set expected_rejection only from an explicit public task requirement. A generic "
        "program exception does not establish the intended business rejection. "
        "For accepted pass/fail, establish each edit's correct input, acceptance and final "
        "field comparisons. For automatic creation, cite the pre-creation state, creation "
        "response and identified new record. Use blocked when required evidence is missing. "
        + PROFILE_RULES[profile] + "\nReturn this structure with actual readings:\n"
        + json.dumps(example)
    )


def to_facts(answer):
    facts = copy.deepcopy(answer)
    facts.pop("observation")
    if facts["submission"]["evidence"] is not None:
        facts["submission"]["evidence"].pop("observation")
    return facts


def render_facts(facts):
    answer = copy.deepcopy(facts)
    status = answer["submission"]["status"]
    evidence = answer["submission"]["evidence"]
    if evidence is not None:
        evidence["observation"] = f"Submission status: {status}; screenshot step {evidence['step']}."
    comparisons = [reading["result_matches_request"] for reading in answer["field_readings"]]
    answer["observation"] = (
        f"Submission: {status}. Final record observed: {str(answer['result_observed']).lower()}. "
        f"Final field comparisons: {comparisons.count(True)} matching, "
        f"{comparisons.count(False)} mismatching, {comparisons.count(None)} unestablished. "
        f"Verdict: {answer['verdict']}."
    )
    return answer


def parse_facts(raw, selected_steps, profile="persistence"):
    facts = json.loads(raw)
    if "observation" in facts or (
        facts["submission"]["evidence"] is not None
        and set(facts["submission"]["evidence"]) != {"step"}
    ):
        raise ValueError("evidence_facts_v1 contains facts only")
    return parse_review(json.dumps(render_facts(facts)), selected_steps, profile)


def facts_schema(selected_steps):
    schema = json_schema(selected_steps)
    schema["properties"].pop("observation")
    schema["required"].remove("observation")
    evidence = schema["properties"]["submission"]["properties"]["evidence"]["anyOf"][1]
    evidence["properties"].pop("observation")
    evidence["required"].remove("observation")
    return schema
